import java.awt.*;
import java.awt.event.*;
import javax.swing.*;

public class RadioButtonDemo extends JFrame implements ActionListener {

    JRadioButton bird, cat, dog, rabbit, pig;
        JLabel imageLabel;
            ButtonGroup group;

                public RadioButtonDemo() {
                        setTitle("RadioButtonDemo");
                                setSize(600, 400);
                                        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
                                                setLayout(new FlowLayout());

                                                        bird = new JRadioButton("Bird");
                                                                cat = new JRadioButton("Cat");
                                                                        dog = new JRadioButton("Dog");
                                                                                rabbit = new JRadioButton("Rabbit");
                                                                                        pig = new JRadioButton("Pig");

                                                                                                group = new ButtonGroup();
                                                                                                        group.add(bird);
                                                                                                                group.add(cat);
                                                                                                                        group.add(dog);
                                                                                                                                group.add(rabbit);
                                                                                                                                        group.add(pig);

                                                                                                                                                bird.addActionListener(this);
                                                                                                                                                        cat.addActionListener(this);
                                                                                                                                                                dog.addActionListener(this);
                                                                                                                                                                        rabbit.addActionListener(this);
                                                                                                                                                                                pig.addActionListener(this);

                                                                                                                                                                                        JPanel left = new JPanel();
                                                                                                                                                                                                left.setLayout(new GridLayout(5, 1));
                                                                                                                                                                                                        left.add(bird);
                                                                                                                                                                                                                left.add(cat);
                                                                                                                                                                                                                        left.add(dog);
                                                                                                                                                                                                                                left.add(rabbit);
                                                                                                                                                                                                                                        left.add(pig);

                                                                                                                                                                                                                                                imageLabel = new JLabel();
                                                                                                                                                                                                                                                        imageLabel.setPreferredSize(new Dimension(250, 250));

                                                                                                                                                                                                                                                                add(left);
                                                                                                                                                                                                                                                                        add(imageLabel);

                                                                                                                                                                                                                                                                                setVisible(true);
                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                        @Override
                                                                                                                                                                                                                                                                                            public void actionPerformed(ActionEvent e) {

                                                                                                                                                                                                                                                                                                    String pet = "";
                                                                                                                                                                                                                                                                                                            String image = "";

                                                                                                                                                                                                                                                                                                                    if (bird.isSelected()) {
                                                                                                                                                                                                                                                                                                                                pet = "Bird";
                                                                                                                                                                                                                                                                                                                                            image = "bird.jpg";
                                                                                                                                                                                                                                                                                                                                                    } else if (cat.isSelected()) {
                                                                                                                                                                                                                                                                                                                                                                pet = "Cat";
                                                                                                                                                                                                                                                                                                                                                                            image = "cat.jpg";
                                                                                                                                                                                                                                                                                                                                                                                    } else if (dog.isSelected()) {
                                                                                                                                                                                                                                                                                                                                                                                                pet = "Dog";
                                                                                                                                                                                                                                                                                                                                                                                                            image = "dog.jpg";
                                                                                                                                                                                                                                                                                                                                                                                                                    } else if (rabbit.isSelected()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                pet = "Rabbit";
                                                                                                                                                                                                                                                                                                                                                                                                                                            image = "rabbit.jpg";
                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else if (pig.isSelected()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                pet = "Pig";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            image = "pig.jpg";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            imageLabel.setIcon(new ImageIcon(image));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    JOptionPane.showMessageDialog(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    this,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "You selected: " + pet,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Selection",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    JOptionPane.INFORMATION_MESSAGE);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            public static void main(String[] args) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    new RadioButtonDemo();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }